        this.evolvingGroups = evolvingGroups
        this.reservedBlockCount = reservedBlockCount
        this.queuedPrompts = queuedPrompts
        this.runId = runId
        if (stableGroupsChanged) this.dispatchEvent(new Event(STABLE_GROUPS_CHANGED_EVENT))
